    Zsh,
}

struct MainArgs {
    file: Option<String>,
    hscale: f64,
    vscale: f64,
    padding: Option<u32>,
    encoding: Encoding,
}

enum Command {
    Render(MainArgs),
    Completion(Shell),
    Help(Vec<String>),
    PrintMainHelp,
    PrintVersion,
}

fn basename(s: &str) -> String {
    Path::new(s)
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| s.to_string())
}

fn main_help_text(bin: &str) -> String {
    format!(
        "{}\n\n\
Usage: {} [OPTIONS] [FILE] [COMMAND]\n\n\
Commands:\n  \
completion\n          Generate shell completion file\n  \
