[COMMAND]...\n          Print help for the subcommand(s)\n",
        bin
    )
}

fn main_usage(bin: &str) -> String {
    format!("Usage: {} [OPTIONS] [FILE] [COMMAND]", bin)
}

fn completion_usage(bin: &str) -> String {
    format!("Usage: {} completion <SHELL>", bin)
}

fn try_help(bin: &str) -> String {
    format!("\nFor more information, try '--help'.\n")
}

fn _unused_bin_suppress(_: &str) {} // silence dead code if any

fn print_err(msg: &str) {
    let _ = writeln!(io::stderr(), "{}", msg);
}

fn fail_parse(msg: &str, usage: &str) -> ExitCode {
    eprintln!("error: {}\n", msg);
    eprintln!("{}\n", usage);
    eprintln!("For more information, try '--help'.");
    ExitCode::from(2)
}

// Parse args and dispatch.
fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let bin = basename(&argv[0]);
    match parse(&argv, &bin) {
        Ok(cmd) => run(cmd, &bin),
        Err(code) => code,
    }
}

// ---- Parsing ----

fn parse(argv: &[String], bin: &str) -> Result<Command, ExitCode> {
    // argv[0] is program. Parse from argv[1..].
    let mut args: Vec<String> = argv[1..].to_vec();
    let main_usage_line = main_usage(bin);

    // Options
    let mut file: Option<String> = None;
    let mut hscale: f64 = 1.0;
    let mut vscale: f64 = 1.0;
    let mut padding: Option<u32> = None;
    let mut encoding = Encoding::Utf8Lossy;

    let mut i = 0;
    let mut positional_seen = false;
    let mut after_dash_dash = false;

    // We may encounter a subcommand. When we do, remaining args go to that subcommand.
    while i < args.len() {
        let a = args[i].clone();
        if !after_dash_dash {
            if a == "--" {
                after_dash_dash = true;
                i += 1;
                continue;
            }
            if a == "-h" || a == "--help" {
                return Ok(Command::PrintMainHelp);
            }
            if a == "--version" {
                return Ok(Command::PrintVersion);
            }
            // Long options with value
            if let Some((name, val)) = split_long_opt(&a) {
                match name {
                    "--horizontal-scale" => {
                        let v = fetch_value(val, &args, &mut i, "--horizontal-scale <HSCALE>", &main_usage_line)?;
                        hscale = parse_float(&v, "--horizontal-scale <HSCALE>", &main_usage_line)?;
                    }
                    "--vertical-scale" => {
                        let v = fetch_value(val, &args, &mut i, "--vertical-scale <VSCALE>", &main_usage_line)?;
                        vscale = parse_float(&v, "--vertical-scale <VSCALE>", &main_usage_line)?;
                    }
                    "--padding" => {
                        let v = fetch_value(val, &args, &mut i, "--padding <PADDING>", &main_usage_line)?;
                        padding = Some(parse_u32(&v, "--padding <PADDING>", &main_usage_line)?);
                    }
                    "--encoding" => {
                        let v = fetch_value(val, &args, &mut i, "--encoding <ENCODING>", &main_usage_line)?;
                        encoding = parse_encoding(&v, &main_usage_line)?;
                    }
                    _ => {
                        return Err(unexpected_arg(&a, &main_usage_line, true));
                    }
                }
                i += 1;
                continue;
            }
            // Short options
            if a.starts_with('-') && a.len() > 1 && !a.starts_with("--") {
                // Could be -H VAL or -HVAL or -V VAL
                let rest = &a[1..];
                let (opt_char, tail) = {
                    let mut chars = rest.chars();
                    let c = chars.next().unwrap();
                    let tail: String = chars.collect();
                    (c, tail)
                };
                match opt_char {
                    'h' => {
                        if tail.is_empty() {
                            return Ok(Command::PrintMainHelp);
                        } else {
                            return Err(unexpected_arg(&a, &main_usage_line, true));
                        }
                    }
                    'H' => {
                        let v = if !tail.is_empty() {
                            tail
                        } else {
                            get_next_value(&args, &mut i, "--horizontal-scale <HSCALE>", &main_usage_line)?
                        };
                        hscale = parse_float(&v, "--horizontal-scale <HSCALE>", &main_usage_line)?;
                    }
                    'V' => {
                        let v = if !tail.is_empty() {
                            tail
                        } else {
                            get_next_value(&args, &mut i, "--vertical-scale <VSCALE>", &main_usage_line)?
                        };
                        vscale = parse_float(&v, "--vertical-scale <VSCALE>", &main_usage_line)?;
                    }
                    _ => {
                        return Err(unexpected_arg(&a, &main_usage_line, true));
                    }
                }
                i += 1;
                continue;
            }
        }
        // Positional: check if subcommand
        if !positional_seen && !after_dash_dash && (a == "completion" || a == "help") {
            // dispatch to subcommand
            let rest: Vec<String> = args[i + 1..].to_vec();
            return parse_subcommand(&a, rest, bin);
        }
        // FILE positional
        if file.is_none() {
            file = Some(a);
            positional_seen = true;
            i += 1;
            continue;
        }
        // If FILE already set, try to interpret as subcommand
        if a == "completion" || a == "help" {
            let rest: Vec<String> = args[i + 1..].to_vec();
            // We still have the main args: file/hscale/vscale/padding/encoding don't matter for subcommand dispatch.
            return parse_subcommand(&a, rest, bin);
        }
        return Err(unexpected_arg(&a, &main_usage_line, false));
    }

    Ok(Command::Render(MainArgs {
        file,
        hscale,
        vscale,
        padding,
        encoding,
    }))
}

fn split_long_opt(a: &str) -> Option<(&str, Option<&str>)> {
    if !a.starts_with("--") {
        return None;
    }
    if let Some(eq_idx) = a.find('=') {
        Some((&a[..eq_idx], Some(&a[eq_idx + 1..])))
    } else {
        Some((a, None))
    }
}

fn fetch_value(
    inline_val: Option<&str>,
    args: &[String],
    i: &mut usize,
    opt_name: &str,
    usage: &str,
) -> Result<String, ExitCode> {
    if let Some(v) = inline_val {
        Ok(v.to_string())
    } else {
        get_next_value(args, i, opt_name, usage)
    }
}

fn get_next_value(
    args: &[String],
    i: &mut usize,
    opt_name: &str,
    usage: &str,
) -> Result<String, ExitCode> {
    if *i + 1 >= args.len() {
        return Err(missing_value(opt_name, usage));
    }
    *i += 1;
    Ok(args[*i].clone())
}

fn missing_value(opt: &str, usage: &str) -> ExitCode {
    eprintln!("error: a value is required for '{}' but none was supplied\n", opt);
    eprintln!("{}\n", usage);
    eprintln!("For more information, try '--help'.");
    ExitCode::from(2)
}

fn parse_float(s: &str, opt: &str, usage: &str) -> Result<f64, ExitCode> {
    match s.parse::<f64>() {
        Ok(v) => Ok(v),
        Err(_) => {
            eprintln!("error: invalid value '{}' for '{}': invalid float literal\n", s, opt);
            eprintln!("{}\n", usage);
            eprintln!("For more information, try '--help'.");
            Err(ExitCode::from(2))
        }
    }
}

fn parse_u32(s: &str, opt: &str, usage: &str) -> Result<u32, ExitCode> {
    match s.parse::<u32>() {
        Ok(v) => Ok(v),
        Err(e) => {
            // Match Rust's "invalid digit found in string" / "number too large" / etc.
            let msg = format!("{}", e);
            eprintln!("error: invalid value '{}' for '{}': {}\n", s, opt, msg);
            eprintln!("{}\n", usage);
            eprintln!("For more information, try '--help'.");
            Err(ExitCode::from(2))
        }
    }
}

fn parse_encoding(s: &str, usage: &str) -> Result<Encoding, ExitCode> {
    match s {
        "utf8-lossy" => Ok(Encoding::Utf8Lossy),
        "utf8" => Ok(Encoding::Utf8),
        _ => {
            eprintln!(
                "error: invalid value '{}' for '--encoding <ENCODING>'\n  [possible values: utf8-lossy, utf8]\n",
                s
            );
            eprintln!("{}\n", usage);
            eprintln!("For more information, try '--help'.");
            Err(ExitCode::from(2))
        }
    }
}

fn unexpected_arg(a: &str, usage: &str, is_option_like: bool) -> ExitCode {
    if is_option_like || a.starts_with('-') {
        eprintln!("error: unexpected argument '{}' found\n", a);
        eprintln!("  tip: to pass '{}' as a value, use '-- {}'\n", a, a);
    } else {
        eprintln!("error: unexpected argument '{}' found\n", a);
    }
    eprintln!("{}\n", usage);
    eprintln!("For more information, try '--help'.");
    ExitCode::from(2)
}

fn parse_subcommand(name: &str, args: Vec<String>, bin: &str) -> Result<Command, ExitCode> {
    match name {
        "completion" => parse_completion(args, bin),
        "help" => Ok(Command::Help(args)),
        _ => unreachable!(),
    }
}

fn parse_completion(args: Vec<String>, bin: &str) -> Result<Command, ExitCode> {
    let usage = completion_usage(bin);
    let mut shell: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "-h" || a == "--help" {
            println!("{}", completion_help_text(bin).trim_end());
            return Err(ExitCode::SUCCESS);
        }
        if a.starts_with('-') && a != "-" {
            return Err(unexpected_arg(a, &usage, true));
        }
        if shell.is_none() {
            shell = Some(a.clone());
            i += 1;
            continue;
        }
        return Err(unexpected_arg(a, &usage, false));
    }
    let sh = match shell {
        Some(s) => s,
        None => {
            eprintln!("error: the following required arguments were not provided:\n  <SHELL>\n");
            eprintln!("{}\n", usage);
            eprintln!("For more information, try '--help'.");
            return Err(ExitCode::from(2));
        }
    };
    let parsed = match sh.as_str() {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        "zsh" => Shell::Zsh,
        _ => {
            eprintln!(
                "error: invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]\n",
                sh
            );
            eprintln!("{}\n", usage);
            eprintln!("For more information, try '--help'.");
            return Err(ExitCode::from(2));
        }
    };
    Ok(Command::Completion(parsed))
}

// ---- Execution ----

fn run(cmd: Command, bin: &str) -> ExitCode {
    match cmd {
        Command::PrintMainHelp => {
            print!("{}", main_help_text(bin));
            ExitCode::SUCCESS
        }
        Command::PrintVersion => {
            println!("{}", VERSION);
            ExitCode::SUCCESS
        }
        Command::Help(cmds) => run_help(cmds, bin),
        Command::Completion(shell) => {
            output_completion(shell);
            ExitCode::SUCCESS
        }
        Command::Render(args) => render(args),
    }
}

fn run_help(cmds: Vec<String>, bin: &str) -> ExitCode {
    // No subcommands => print main help
    // With subcommand => print subcommand help
    // Multiple => iterate?
    if cmds.is_empty() {
        print!("{}", main_help_text(bin));
        return ExitCode::SUCCESS;
    }
    // Find valid subcommand
    let first = &cmds[0];
    match first.as_str() {
        "completion" => {
            print!("{}", completion_help_text(bin));
            ExitCode::SUCCESS
        }
        "help" => {
            print!("{}", help_help_text(bin));
            ExitCode::SUCCESS
        }
        other => {
            eprintln!("error: unrecognized subcommand '{}'\n", other);
            eprintln!("{}\n", main_usage(bin));
            eprintln!("For more information, try '--help'.");
            ExitCode::from(2)
        }
    }
}

fn output_completion(shell: Shell) {
    let bytes: &[u8] = match shell {
        Shell::Bash => include_bytes!("../assets/completion.bash"),
        Shell::Elvish => include_bytes!("../assets/completion.elvish"),
        Shell::Fish => include_bytes!("../assets/completion.fish"),
        Shell::PowerShell => include_bytes!("../assets/completion.powershell"),
        Shell::Zsh => include_bytes!("../assets/completion.zsh"),
    };
    let _ = io::stdout().write_all(bytes);
}

// ---- Rendering ----

fn render(args: MainArgs) -> ExitCode {
    let reader: Box<dyn Read> = match &args.file {
        Some(p) => match File::open(p) {
            Ok(f) => Box::new(f),
            Err(e) => {
                eprintln!("code-minimap: {}", e);
                return ExitCode::from(1);
            }
        },
        None => Box::new(io::stdin()),
    };
    let mut br = BufReader::new(reader);

    // We read entire stream, apply encoding, then split by newlines
    let mut buf: Vec<u8> = Vec::new();
    if let Err(e) = br.read_to_end(&mut buf) {
        eprintln!("code-minimap: {}", e);
        return ExitCode::from(1);
    }

    let text: String = match args.encoding {
        Encoding::Utf8Lossy => String::from_utf8_lossy(&buf).into_owned(),
        Encoding::Utf8 => match String::from_utf8(buf) {
            Ok(s) => s,
            Err(_) => {
                eprintln!("code-minimap: stream did not contain valid UTF-8");
                return ExitCode::from(1);
            }
        },
    };

    // Split into lines like BufRead::lines: splits on '\n', strips trailing '\r'
    let lines: Vec<&str> = split_lines(&text);

    // Now each line has byte length etc. We need to:
    // Compute for each line:
    //   - first_non_ws_byte_offset (in the trimmed line -- trimmed of trailing whitespace)
    //   - width (= byte offset of start of last non-ws char + 1)
    // then apply vscale, hscale and produce braille output.

    render_lines(&lines, args.hscale, args.vscale, args.padding);
    ExitCode::SUCCESS
}

fn split_lines(text: &str) -> Vec<&str> {
    // Mimic BufRead::lines(): split on '\n', strip trailing '\r' from each. Empty trailing piece is dropped.
    let bytes = text.as_bytes();
    let mut out = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'\n' {
            let mut end = i;
            if end > start && bytes[end - 1] == b'\r' {
                end -= 1;
            }
            out.push(&text[start..end]);
            start = i + 1;
        }
        i += 1;
    }
    if start < bytes.len() {
        out.push(&text[start..]);
    }
    out
}

// Compute per-line (first_col, width)
fn line_info(line: &str) -> Option<(usize, usize)> {
    // Find byte offset of first non-whitespace char and byte offset of start of last non-whitespace char.
    let mut first: Option<usize> = None;
    let mut last_start: usize = 0;
    for (idx, ch) in line.char_indices() {
        if !ch.is_whitespace() {
            if first.is_none() {
                first = Some(idx);
            }
            last_start = idx;
        }
    }
    first.map(|f| (f, last_start + 1))
}

fn render_lines(lines: &[&str], hscale: f64, vscale: f64, padding: Option<u32>) {
    // Clamp vscale at 1.0 maximum (empirically observed)
    let vscale_eff = if vscale > 1.0 { 1.0 } else { vscale };

    // Compute max output col width
    let n = lines.len();
    if n == 0 {
        return;
    }

    // Determine output col width = floor(max_line_width * hscale)
    let mut max_width = 0usize;
    let mut line_ranges: Vec<Option<(usize, usize)>> = Vec::with_capacity(n);
    for l in lines {
        let info = line_info(l);
        if let Some((_, w)) = info {
            if w > max_width {
                max_width = w;
            }
        }
        line_ranges.push(info);
    }

    let out_cols = (max_width as f64 * hscale).floor() as usize;

    // Determine vline count
    // vline for input line i = floor(i * vscale_eff)
    // number of vlines = last vline index + 1 (but we still need to fill up to last_vline)
    let max_vline = if n == 0 { 0 } else { floor_mul(n - 1, vscale_eff) };
    let vline_count = max_vline + 1;
    let braille_rows = (vline_count + 3) / 4;

    // Precompute vline for each input line
    let mut vlines: Vec<usize> = Vec::with_capacity(n);
    for i in 0..n {
        vlines.push(floor_mul(i, vscale_eff));
    }

    // For each output col c, the corresponding input col = floor(c / hscale)
    // But we need to precompute the filled state per (vline, col) cell.
    // Then aggregate into braille chars.

    // Since vlines can be combined (multiple input lines with same vline), we OR.
    // Memory: out_cols * vline_count bits. For large input, this could be huge. But OK for now.

    // Fast path: compute per vline: first_col (= floor(first_non_ws * hscale)) actually not quite.
    // Since any input col in [first_ws, width) is filled, and output col c maps to input floor(c/hscale),
    // then output col c is filled iff first_non_ws <= floor(c/hscale) < width.
    // For multiple input lines in the same vline, we OR, meaning output col c is filled iff ANY input line
    // in that vline has first_non_ws <= floor(c/hscale) < width.

    // Equivalently for each vline, compute the union of [first_col_out, last_col_out] ranges per input line.
    // But in general this union may be complex. Let's just process cell by cell.

    let stdout = io::stdout();
    let mut out = stdout.lock();

    let pad_target = padding.map(|p| p as usize).unwrap_or(0);

    // For each braille row, compute characters.
    for brow in 0..braille_rows {
        let row_first_v = brow * 4;
        let row_last_v = row_first_v + 3; // may exceed vline_count-1

        // Number of braille chars per row
        let out_chars = (out_cols + 1) / 2;
        // But if out_cols == 0, we still need to output the empty braille row "⠀" if there are lines.
        let effective_chars = if out_chars == 0 { 1 } else { out_chars };

        let mut line_bytes: Vec<u8> = Vec::new();
        for chr in 0..effective_chars {
            let base_col = chr * 2;
            let mut bits: u8 = 0;
            for dy in 0..4usize {
                let v = row_first_v + dy;
                if v >= vline_count {
                    break;
                }
                // For each input line mapping to this vline, check cols base_col and base_col+1.
                for i in 0..n {
                    if vlines[i] != v {
                        continue;
                    }
                    if let Some((first_ws, width)) = line_ranges[i] {
                        for dx in 0..2usize {
                            let c = base_col + dx;
                            if c >= out_cols {
                                continue;
                            }
                            let input_col = div_floor(c, hscale);
                            if input_col >= first_ws && input_col < width {
                                bits |= dot_bit(dx, dy);
                            }
                        }
                    }
                }
            }
            let cp: u32 = 0x2800 + bits as u32;
            let ch = char::from_u32(cp).unwrap();
            let mut tmp = [0u8; 4];
            let s = ch.encode_utf8(&mut tmp);
            line_bytes.extend_from_slice(s.as_bytes());
        }

        // Apply padding: number of visual chars = effective_chars. If pad_target > effective_chars, add spaces.
        if pad_target > effective_chars {
            for _ in 0..(pad_target - effective_chars) {
                line_bytes.push(b' ');
            }
        }
        line_bytes.push(b'\n');
        let _ = out.write_all(&line_bytes);
    }
}

fn floor_mul(i: usize, s: f64) -> usize {
    ((i as f64) * s).floor() as usize
}

fn div_floor(c: usize, hscale: f64) -> usize {
    ((c as f64) / hscale).floor() as usize
}

fn dot_bit(dx: usize, dy: usize) -> u8 {
    // dx in {0,1}, dy in {0..3}
    // Braille dots:
    //   col 0: rows 0,1,2,3 = dots 1,2,3,7 → bits 0,1,2,6 (0x01,0x02,0x04,0x40)
    //   col 1: rows 0,1,2,3 = dots 4,5,6,8 → bits 3,4,5,7 (0x08,0x10,0x20,0x80)
    match (dx, dy) {
        (0, 0) => 0x01,
        (0, 1) => 0x02,
        (0, 2) => 0x04,
        (0, 3) => 0x40,
        (1, 0) => 0x08,
        (1, 1) => 0x10,
        (1, 2) => 0x20,
        (1, 3) => 0x80,
        _ => 0,
    }
}
