        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| s.to_string())
}

fn main_help_text(bin: &str) -> String {
    format!(
        "{}\n\n\
Usage: {} [OPTIONS] [FILE] [COMMAND]\n\n\
Commands:\n  \
completion\n          Generate shell completion file\n  \
